/* PLOTR poster compositor. All typography and interactions are path geometry. */
let posterGeometry=[],posterSamples=[],posterField=null,posterOverflow=false,activeBlock=0;
const blockDefaults={font:'mono',text:'NOUVEAU TEXTE',x:8,y:40,size:18,width:100,tracking:1.2,leading:1.35,align:'left',rotation:0,slant:0,weight:.45,color:'#333a36',visible:true,influence:true,style:'single'};
function newPoster(){return {enabled:false,effect:'repel',radius:13,strength:2.5,clearance:2.5,blocks:[{...blockDefaults,text:'FREE\nFORM',size:30,x:8,y:16,tracking:1.8},{...blockDefaults,text:'EXPLORATIONS GENERATIVES',size:3.2,x:8,y:8,tracking:.7,weight:.22,influence:true},{...blockDefaults,text:'BLOCK {height}\n{date}',size:3,x:8,y:88,tracking:.5,leading:1.8,weight:.2,influence:true}]}}
function normalizeState(){s.params??={};if(s.engine==='type'&&s.params.repeatSize===undefined){const h=pageDimensions()[1];s.params.repeatSize=Math.max(1,Math.min(80,(h-2*s.margin)/(s.params.density||16)*.65))}for(const [key,value] of Object.entries(defaults[s.engine]))if(s.params[key]===undefined)s.params[key]=value;if(!s.poster)s.poster=newPoster();for(const [key,value] of Object.entries(newPoster()))if(s.poster[key]===undefined)s.poster[key]=value;for(const b of s.poster.blocks)for(const [key,value] of Object.entries(blockDefaults))if(b[key]===undefined)b[key]=value;activeBlock=Math.min(activeBlock,Math.max(0,s.poster.blocks.length-1))}
function pageDimensions(){return {square:[210,210],portrait:[210,297],landscape:[297,210],a3portrait:[297,420],a3landscape:[420,297]}[s.format]||[210,210]}
function drawingPalette(){return s.poster?.enabled?[...palette(),...s.poster.blocks.map(b=>b.color)]:palette()}
function normalizedText(text,family='mono'){const value=String(text).replace(/\r/g,'').replace(/\t/g,' ');return family==='mono'?value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase():value.normalize('NFC')}
function textGeometry(block){const [w,h]=dims,m=s.margin,scaleX=block.size*block.width/100,anchor=[m+(w-2*m)*block.x/100,m+(h-2*m)*block.y/100],angle=block.rotation*Math.PI/180,co=Math.cos(angle),si=Math.sin(angle),result=[];
 for(const [row,line]of normalizedText(block.text,block.font).split('\n').entries()){const layout=layoutLine(line,block.font,scaleX,block.tracking),offset=block.align==='center'?-layout.width/2:block.align==='right'?-layout.width:0;for(const item of layout.items){for(const stroke of item.glyph.p){const pts=stroke.map(([gx,gy])=>{let x=offset+item.x+gx*scaleX+(1-gy)*block.size*block.slant/100,y=row*block.size*block.leading+gy*block.size;return[anchor[0]+x*co-y*si,anchor[1]+x*si+y*co]});result.push(pts);if(block.style==='double')result.push(pts.map(v=>[v[0]+block.size*.025,v[1]+block.size*.025]))}}}return result}
function generateType(p,n,colors){const [w,h]=dims,m=s.margin;if(p.layout==='compose'){const geom=textGeometry({...blockDefaults,...p,text:p.text,x:p.align==='center'?50:p.align==='right'?100:0,y:p.y,rotation:0,weight:s.weight});for(const [i,pts]of geom.entries())add(pts.map(([x,y])=>[x,y+Math.sin(x/w*Math.PI*3+phase)*p.amplitude]),i%colors);return}
 const lines=normalizedText(p.text||'PLOTR',p.font).split('\n'),rowH=(h-2*m)/p.density,maxPerRow=Math.floor(18000/p.density);
 for(let row=0;row<p.density;row++){const text=Array.from(lines[row%lines.length]);if(!text.length)continue;let x=m,idx=0,base=m+(row+.5)*rowH;while(x<w-m){if(idx>=maxPerRow){typeLimited=true;break}let ch=text[idx%text.length],sz=p.repeatSize*(1+p.scale*.35*n(x*.035,row*.2)),scaleX=sz*p.width/100,g=typeGlyph(p.font,ch);if(idx)x+=fontKern(p.font,text[(idx-1)%text.length],ch)*scaleX;
 for(const stroke of g.p){add(stroke.map(([gx,gy])=>{let xx=x+gx*scaleX+(1-gy)*sz*p.slant/100;return[xx,base+(gy-.5)*sz+Math.sin(xx/w*Math.PI*3+phase+row*.12)*p.amplitude]}),row%colors)}x+=Math.max(.5,g.a*scaleX+p.tracking);idx++}}}
function preparePoster(){posterGeometry=[];posterSamples=[];posterField=null;posterOverflow=false;if(!s.poster.enabled)return;for(let i=0;i<s.poster.blocks.length;i++){const b=s.poster.blocks[i];if(!b.visible)continue;const geom=textGeometry(b);for(const pts of geom){posterGeometry.push({points:pts,layer:palette().length+i,weight:b.weight});for(const [x,y]of pts)if(x<s.margin||y<s.margin||x>dims[0]-s.margin||y>dims[1]-s.margin)posterOverflow=true;if(b.influence)for(let j=1;j<pts.length;j++){let a=pts[j-1],z=pts[j],steps=Math.max(1,Math.ceil(Math.hypot(z[0]-a[0],z[1]-a[1])/1.5));for(let k=0;k<steps;k++){let t=k/steps;posterSamples.push([a[0]+(z[0]-a[0])*t,a[1]+(z[1]-a[1])*t])}posterSamples.push(z)}}}
 if(!posterSamples.length||s.poster.effect==='overlay'||s.poster.effect==='source')return;
 const step=2,nx=Math.ceil(dims[0]/step)+2,ny=Math.ceil(dims[1]/step)+2,ds=new Float32Array(nx*ny).fill(Infinity),xs=new Float32Array(nx*ny),ys=new Float32Array(nx*ny),reach=Math.max(s.poster.radius,s.poster.clearance+3)+3;
 for(const [x,y]of posterSamples){const x0=Math.max(0,Math.floor((x-reach)/step)),x1=Math.min(nx-1,Math.ceil((x+reach)/step)),y0=Math.max(0,Math.floor((y-reach)/step)),y1=Math.min(ny-1,Math.ceil((y+reach)/step));for(let gy=y0;gy<=y1;gy++)for(let gx=x0;gx<=x1;gx++){let dx=gx*step-x,dy=gy*step-y,d=dx*dx+dy*dy,id=gy*nx+gx;if(d<ds[id]){ds[id]=d;xs[id]=x;ys[id]=y}}}
 const fx=new Float32Array(nx*ny),fy=new Float32Array(nx*ny),distance=new Float32Array(nx*ny);for(let gy=0;gy<ny;gy++)for(let gx=0;gx<nx;gx++){let id=gy*nx+gx,d=Math.sqrt(ds[id]);distance[id]=Number.isFinite(d)?d:reach;let f=Math.max(0,1-d/s.poster.radius);if(d>.01){fx[id]=(gx*step-xs[id])/d*f*f;fy[id]=(gy*step-ys[id])/d*f*f}}posterField={nx,ny,step,fx,fy,distance}}
function sampleField(arr,x,y){const {nx,ny,step}=posterField;let gx=Math.max(0,Math.min(nx-2,x/step)),gy=Math.max(0,Math.min(ny-2,y/step)),ix=Math.floor(gx),iy=Math.floor(gy),tx=gx-ix,ty=gy-iy,id=iy*nx+ix;return arr[id]*(1-tx)*(1-ty)+arr[id+1]*tx*(1-ty)+arr[id+nx]*(1-tx)*ty+arr[id+nx+1]*tx*ty}
function textForce(x,y){if(!posterField)return[0,0];return[sampleField(posterField.fx,x,y),sampleField(posterField.fy,x,y)]}
function posterSource(r){if(!s.poster.enabled||s.poster.effect!=='source'||!posterSamples.length)return null;return posterSamples[Math.floor(r()*posterSamples.length)]}
function applyPoster(){if(!s.poster.enabled)return;const effect=s.poster.effect;if(posterField&&(effect==='repel'||effect==='reserve')){let original=paths;paths=[];for(const path of original){let part=[];const flush=()=>{if(part.length>1)add(part,path.layer);part=[]};for(let i=1;i<path.points.length;i++){const a=path.points[i-1],b=path.points[i],steps=Math.max(1,Math.ceil(dist(a,b)/1.2));for(let j=i===1?0:1;j<=steps;j++){let t=j/steps,x=a[0]+(b[0]-a[0])*t,y=a[1]+(b[1]-a[1])*t;if(effect==='repel'&&s.engine!=='flow'){const f=textForce(x,y);x+=f[0]*s.poster.strength*3;y+=f[1]*s.poster.strength*3}if(sampleField(posterField.distance,x,y)<s.poster.clearance){flush()}else part.push([x,y])}}flush()}}
 for(const p of posterGeometry){const before=paths.length;add(p.points,p.layer);for(let j=before;j<paths.length;j++)paths[j].weight=p.weight}}
function numberControl(key,label,value,min,max,step=1,kind='block'){return `<label>${label}<input class="param-number" type="number" aria-label="${label} — valeur" data-${kind}-number="${key}" value="${value}" min="${min}" max="${max}" step="${step}"><input aria-label="${label}" type="range" data-${kind}="${key}" value="${value}" min="${min}" max="${max}" step="${step}"></label>`}
function typeControlsHTML(){let p=s.params;return `<label>Composition<select id="typeLayout"><option value="repeat">Motif répété</option><option value="compose">Texte composé · multiligne</option></select></label>${fontControl('typeFont',p.font)}<label>Vos lignes<textarea id="words" rows="4" maxlength="2000" aria-label="Texte de la composition"></textarea></label>${bitcoinTextControls("words")}<div id="typeRepeatFields">${numberControl('repeatSize','Corps (mm)',p.repeatSize,1,80,.25,'type')}${numberControl('density','Nombre de lignes',p.density,1,120,1,'type')}<button id="fitTypeRows" class="wide-button">Ajuster les lignes au corps</button><p class="tip">Jusqu’à 120 lignes réparties sur la toile. Le corps est indépendant : les lettres peuvent se chevaucher.</p></div><div id="typeComposeFields">${numberControl('size','Corps (mm)',p.size,1,80,.25,'type')}${numberControl('leading','Interlignage (×)',p.leading,.6,3,.05,'type')}${numberControl('y','Position verticale (%)',p.y,0,90,1,'type')}<label>Alignement<select id="typeAlign"><option value="left">Gauche</option><option value="center">Centré</option><option value="right">Droite</option></select></label></div>${numberControl('tracking','Approche (mm)',p.tracking,0,10,.1,'type')}${numberControl('width','Largeur des lettres (%)',p.width,35,160,1,'type')}${numberControl('slant','Inclinaison (%)',p.slant,-30,30,1,'type')}<p id="typeNotice" class="tip"></p>`}

function bindNumeric(kind,obj,callback){for(const el of document.querySelectorAll(`[data-${kind}], [data-${kind}-number]`)){const numeric=el.hasAttribute(`data-${kind}-number`),key=el.getAttribute(`data-${kind}${numeric?'-number':''}`);el.oninput=()=>{if(el.value==='')return;let v=Number(el.value);if(!Number.isFinite(v))return;if(numeric&&(v<+el.min||v>+el.max))return;v=Math.max(+el.min,Math.min(+el.max,v));if(+el.step===1)v=Math.round(v);obj[key]=v;el.value=v;document.querySelectorAll(`[data-${kind}="${key}"], [data-${kind}-number="${key}"]`).forEach(other=>other.value=v);callback();schedule()};if(numeric)el.onchange=()=>{if(el.value===''||!Number.isFinite(Number(el.value)))el.value=obj[key];else el.value=Math.max(+el.min,Math.min(+el.max,+el.value));el.oninput()}}}
function bindTypeControls(){if(s.engine!=='type')return;$('typeLayout').value=s.params.layout;$('typeAlign').value=s.params.align;const show=()=>{$('typeComposeFields').hidden=s.params.layout!=='compose';$('typeRepeatFields').hidden=s.params.layout!=='repeat';document.querySelector('[data-param="scale"]').closest('label').hidden=s.params.layout==='compose'};show();$('typeLayout').onchange=e=>{s.params.layout=e.target.value;show();schedule()};$('typeAlign').onchange=e=>{s.params.align=e.target.value;schedule()};$('typeFont').onchange=e=>{s.params.font=e.target.value;updateFontSpecimen('typeFont',s.params.font);schedule()};$('fitTypeRows').onclick=()=>{s.params.density=Math.max(1,Math.min(120,Math.floor((dims[1]-2*s.margin)/(s.params.repeatSize*1.4))));document.querySelectorAll('[data-type="density"], [data-type-number="density"]').forEach(el=>el.value=s.params.density);schedule();toast(s.params.density+' lignes · espacement de 1,4 × le corps')};bindNumeric('type',s.params,()=>{});updateFontSpecimen('typeFont',s.params.font)}

function posterControls(){let p=s.poster,b=p.blocks[activeBlock];$('posterControls').innerHTML=`<div class="section-label">LA LETTRE DEVIENT PAYSAGE <span class="version">02</span></div><label class="check"><input id="posterEnabled" type="checkbox"> Activer la composition d’affiche</label><div class="preset-row"><button data-preset="editorial">Éditorial</button><button data-preset="source">Émission</button><button data-preset="optical">Optique</button></div><p class="tip">Ces compositions remplacent les blocs et réglages actuels. Enregistrez un favori pour les conserver.</p><label>Dialogue texte / moteur<select id="posterEffect"><option value="overlay">Superposition · texte libre</option><option value="reserve">Réserve · espace autour des lettres</option><option value="repel">Répulsion · dévier les lignes</option><option value="source" ${s.engine!=='flow'?'disabled':''}>Émission · lignes issues des lettres (Flow)</option></select></label><div id="fieldControls">${numberControl('radius','Rayon d’influence (mm)',p.radius,4,40,1,'field')}${numberControl('strength','Force de répulsion',p.strength,.5,6,.1,'field')}${numberControl('clearance','Réserve (mm)',p.clearance,.5,8,.25,'field')}</div><div class="block-toolbar"><span class="section-label">BLOCS TYPOGRAPHIQUES</span><button id="addBlock" title="Ajouter un bloc">＋</button></div><div id="blockList"></div><div class="block-editor">${fontControl('blockFont',b.font)}<label>Texte · retours à la ligne libres<textarea id="blockText" rows="4" maxlength="400"></textarea></label>${bitcoinTextControls("blockText")}<div class="block-actions"><label class="check"><input type="checkbox" id="blockVisible">Visible</label><label class="check"><input type="checkbox" id="blockInfluence">Influence</label></div><label>Dessin des lettres<select id="blockStyle"><option value="single">Tracé simple</option><option value="double">Double trait</option></select></label>${numberControl('size','Corps (mm)',b.size,2,80,.5)}${numberControl('width','Largeur des lettres (%)',b.width,35,160)}${numberControl('tracking','Approche (mm)',b.tracking,0,15,.1)}${numberControl('leading','Interlignage (×)',b.leading,.6,3,.05)}<div class="two-cols">${numberControl('x','Position X (%)',b.x,0,100)}${numberControl('y','Position Y (%)',b.y,0,100)}</div><label>Alignement<select id="blockAlign"><option value="left">Gauche</option><option value="center">Centré</option><option value="right">Droite</option></select></label>${numberControl('rotation','Rotation (°)',b.rotation,-180,180)}${numberControl('slant','Inclinaison (%)',b.slant,-30,30)}${numberControl('weight','Trait (mm)',b.weight,.1,2,.05)}<label class="color-label">Encre du bloc <input type="color" id="blockColor"></label><div class="block-actions"><button id="duplicateBlock">Dupliquer</button><button id="deleteBlock">Supprimer</button></div><p class="tip">Positions relatives à la zone imprimable. L’alignement se fait autour du point X. Les débordements sont coupés aux marges. Polices en contours vectoriels ; la monoligne conserve son alphabet simplifié.</p></div><p id="posterNotice" class="tip"></p>`;
 $('posterEnabled').checked=p.enabled;$('posterEffect').value=p.effect;$('blockText').value=b.text;$('blockVisible').checked=b.visible;$('blockInfluence').checked=b.influence;$('blockStyle').value=b.style;$('blockAlign').value=b.align;$('blockColor').value=b.color;$('blockFont').onchange=e=>{b.font=e.target.value;updateFontSpecimen('blockFont',b.font);schedule()};updateFontSpecimen('blockFont',b.font);
 p.blocks.forEach((block,i)=>{const button=document.createElement('button');button.textContent=(i+1)+' · '+(block.text.split('\n')[0]||'Bloc vide');button.classList.toggle('active',i===activeBlock);button.onclick=()=>{activeBlock=i;posterControls()};$('blockList').append(button)});
 const displayFields=()=>{$('fieldControls').hidden=!['repel','reserve'].includes(p.effect);for(const key of['radius','strength'])document.querySelector(`[data-field="${key}"]`).closest('label').hidden=p.effect!=='repel'};displayFields();$('posterEnabled').onchange=e=>{p.enabled=e.target.checked;updatePosterStatus();schedule()};$('posterEffect').onchange=e=>{p.effect=e.target.value;displayFields();schedule()};$('blockText').oninput=e=>{b.text=e.target.value;let button=$('blockList').children[activeBlock];button.textContent=(activeBlock+1)+' · '+(b.text.split('\n')[0]||'Bloc vide');schedule()};for(const [id,key,check]of[['blockVisible','visible',true],['blockInfluence','influence',true],['blockStyle','style'],['blockAlign','align'],['blockColor','color']])$(id).oninput=e=>{b[key]=check?e.target.checked:e.target.value;schedule()};bindNumeric('block',b,()=>{});bindNumeric('field',p,()=>{});
 $('addBlock').onclick=()=>{if(p.blocks.length>=6)return toast('6 blocs maximum par affiche.');p.blocks.push({...blockDefaults});activeBlock=p.blocks.length-1;posterControls();schedule()};$('duplicateBlock').onclick=()=>{if(p.blocks.length>=6)return toast('6 blocs maximum par affiche.');p.blocks.push({...b,y:Math.min(90,b.y+8)});activeBlock=p.blocks.length-1;posterControls();schedule()};$('deleteBlock').disabled=p.blocks.length===1;$('deleteBlock').onclick=()=>{p.blocks.splice(activeBlock,1);activeBlock=Math.max(0,activeBlock-1);posterControls();schedule()};document.querySelectorAll('[data-preset]').forEach(el=>el.onclick=()=>posterPreset(el.dataset.preset));updatePosterStatus()}
function updatePosterStatus(){if(!$('posterToggle'))return;$('posterToggle').setAttribute('aria-pressed',!!s.poster?.enabled);$('posterToggle').textContent=s.poster?.enabled?'▤ Affiche active':'▤ Mode affiche';if($('posterNotice'))$('posterNotice').textContent=!s.poster.enabled?'Activez le mode affiche pour afficher vos blocs.':posterOverflow?'Un bloc déborde des marges : réduisez son corps ou ajustez sa position.':s.poster.effect==='source'?'Les lignes partent des traits des blocs avec Influence activée. Longueur et densité se règlent dans Réglages.':'Chaque bloc conserve ses réglages et son encre dans les favoris et l’export HTML.'}
function bindPosterUI(){$('posterToggle').onclick=()=>{s.poster.enabled=!s.poster.enabled;document.querySelector('[data-tab="poster"]').click();document.body.classList.remove('focus');if(innerWidth<=650)document.body.classList.add('panel-mobile');posterControls();render()};for(const btn of document.querySelectorAll('[data-engine]')){const original=btn.onclick;btn.onclick=()=>{original();if(s.engine!=='flow'&&s.poster.effect==='source'){s.poster.effect='repel';posterControls();render();toast('Répulsion activée : l’émission est propre à Flow Fields.')}}}}
function posterPreset(name){pause();s.poster=newPoster();s.poster.enabled=true;s.format='portrait';s.margin=16;s.paper='white';s.palette='mono';s.weight=.17;phase=0;s.points=[];activeBlock=0;
 if(name==='editorial'){s.engine='flow';s.params={...defaults.flow,density:190,length:300,frequency:1.3,force:.6};s.poster.blocks[0]={...blockDefaults,text:'FORM\nFOLLOWS\nFEELING',x:5,y:20,size:24,width:85,tracking:1.4,leading:1.4,weight:.65};s.poster.radius=20;s.poster.strength=4;s.poster.clearance=4}
 if(name==='source'){s.engine='flow';s.params={...defaults.flow,density:250,length:160,frequency:1.6,force:.4,amplitude:1.1};s.poster.effect='source';s.poster.blocks[1].influence=false;s.poster.blocks[2].influence=false;s.poster.blocks[0]={...blockDefaults,text:'ORIGIN',x:50,y:43,size:30,width:90,tracking:1.5,align:'center',weight:.8,color:'#b85431'};s.poster.blocks[1].text='EVERY LINE STARTS SOMEWHERE'}
 if(name==='optical'){s.engine='op';s.params={...defaults.op,density:110,amplitude:16,frequency:4};s.poster.effect='reserve';s.poster.clearance=3;s.poster.blocks[0]={...blockDefaults,text:'LESS\nBUT\nBETTER',x:50,y:27,size:28,width:85,tracking:1.8,align:'center',weight:.7};s.poster.blocks[1].text='A STUDY IN OPTICAL RHYTHM'}
 controls();render();toast('Composition chargée · vos mots sont prêts à prendre place')}
